// Package oui resolves the vendor of a MAC address from the IEEE registry
// (MA-L, MA-M and MA-S assignments). The table is embedded at build time and
// generated by tools/ouigen; lookups never touch the network.
package oui

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"net"
	"sort"
	"strconv"
	"strings"
	"sync"
)

//go:embed oui.tsv.gz
var table []byte

// Vendor is the organisation a MAC prefix is registered to.
type Vendor struct {
	Name     string // short, human-friendly name ("AVM")
	Official string // registered name ("AVM Audiovisuelles Marketing und Computersysteme GmbH")
}

type entry struct {
	key uint64
	v   *Vendor
}

type db struct {
	byLen map[int][]entry // prefix length in bits (24, 28, 36) -> sorted entries
}

var (
	once   sync.Once
	loaded *db
	count  int
)

func load() {
	d := &db{byLen: map[int][]entry{}}
	zr, err := gzip.NewReader(bytes.NewReader(table))
	if err != nil {
		loaded = d
		return
	}
	defer zr.Close()
	intern := map[string]*Vendor{}
	sc := bufio.NewScanner(zr)
	sc.Buffer(make([]byte, 64*1024), 64*1024)
	for sc.Scan() {
		parts := strings.Split(sc.Text(), "\t")
		if len(parts) < 2 {
			continue
		}
		prefix := parts[0]
		bits := len(prefix) * 4
		if bits != 24 && bits != 28 && bits != 36 {
			continue
		}
		key, err := strconv.ParseUint(prefix, 16, 64)
		if err != nil {
			continue
		}
		official := parts[1]
		if len(parts) > 2 {
			official = parts[2]
		}
		ik := parts[1] + "\x00" + official
		v, ok := intern[ik]
		if !ok {
			v = &Vendor{Name: parts[1], Official: official}
			intern[ik] = v
		}
		d.byLen[bits] = append(d.byLen[bits], entry{key: key, v: v})
		count++
	}
	for _, es := range d.byLen {
		sort.Slice(es, func(i, j int) bool { return es[i].key < es[j].key })
	}
	loaded = d
}

// Size returns the number of registry entries available.
func Size() int {
	once.Do(load)
	return count
}

// Lookup returns the vendor for mac using longest-prefix match.
func Lookup(mac net.HardwareAddr) (Vendor, bool) {
	if len(mac) != 6 {
		return Vendor{}, false
	}
	once.Do(load)
	var v48 uint64
	for _, b := range mac {
		v48 = v48<<8 | uint64(b)
	}
	for _, bits := range []int{36, 28, 24} {
		key := v48 >> (48 - bits)
		es := loaded.byLen[bits]
		i := sort.Search(len(es), func(i int) bool { return es[i].key >= key })
		if i < len(es) && es[i].key == key {
			v := *es[i].v
			// Large blocks sub-assigned to MA-M/MA-S holders are registered
			// to the IEEE itself; that name is never useful to show.
			if v.Name == "IEEE Registration Authority" {
				continue
			}
			return v, true
		}
	}
	return Vendor{}, false
}

// IsRandomized reports whether mac is a locally administered address, which
// is what phones and laptops use for "private Wi-Fi address" features.
func IsRandomized(mac net.HardwareAddr) bool {
	return len(mac) == 6 && mac[0]&0x02 != 0
}
